#!/usr/bin/env bash
# kvevac-aws.sh: Phase 2 calibration on one g6e.xlarge spot instance, run from AWS CloudShell.
#
# GENERATED by jobs/aws/build.py from jobs/aws/driver.sh. Edit those and rebuild.
#
#   bash kvevac-aws.sh            launch, measure, interrupt with FIS, clean up, summarize
#   bash kvevac-aws.sh resume     continue the latest run (e.g. after CloudShell timed out)
#   bash kvevac-aws.sh cleanup    terminate every kvevac-aws instance and FIS template
#
# What a run does:
#  1. Launches one one-time spot g6e.xlarge (1x L40S) from the Deep Learning Base OSS
#     Nvidia GPU AMI (Ubuntu 22.04), IMDSv2 required, shutdown behaviour "terminate".
#     The instance powers itself off after MAX_MIN minutes, whatever happens here.
#  2. The instance installs vLLM, serves the model with prefix caching off, measures
#     prefill/decode and receiver slowdown, and writes the results to its serial console.
#  3. This script polls `get-console-output`, reassembles the results, then triggers an
#     AWS FIS spot interruption on that instance and records the notice timing.
#  4. It terminates the instance, deletes the FIS template and prints a summary.
# The instance gets no credentials, SSH key, S3 bucket or IAM role. The only IAM change
# is a role named kvevac-fis that FIS uses (created once, kept, costs nothing).
#
# Settings (environment variables): INSTANCE_TYPE (g6e.xlarge), MAX_MIN (90), ROOT_GB
# (150), SUBNET_ID (default: the default VPC's subnets, cheapest zone first), POLL_S (15),
# SKIP_FIS=1, RETRY_MIN (0: keep retrying every zone for this many minutes when there is
# no spot capacity), MARKET (spot; "on-demand" for the calibration measurements only,
# since FIS cannot interrupt an on-demand instance; ON_DEMAND_PRICE, default 1.861 $/h,
# is used for the cost line), and for the instance: MODEL, MAX_MODEL_LEN, VLLM_SPEC,
# PREFILL_CONTEXTS, PREFILL_REPEATS, INTERFERENCE_REPEATS, INTERFERENCE_CONTEXT.
set -euo pipefail

INSTANCE_TYPE="${INSTANCE_TYPE:-g6e.xlarge}"
MAX_MIN="${MAX_MIN:-90}"
ROOT_GB="${ROOT_GB:-150}"
POLL_S="${POLL_S:-15}"
RETRY_MIN="${RETRY_MIN:-0}"
RETRY_EVERY_S="${RETRY_EVERY_S:-300}"
MARKET="${MARKET:-spot}"
ON_DEMAND_PRICE="${ON_DEMAND_PRICE:-1.861}"
case "$MARKET" in spot|on-demand) ;; *) echo "MARKET must be spot or on-demand"; exit 2 ;; esac
NOTICE_WAIT_S="${NOTICE_WAIT_S:-420}"
RUNS="${KVEVAC_RUNS:-$HOME/kvevac-runs}"
AMI_PARAM="${AMI_PARAM:-/aws/service/deeplearning/ami/x86_64/base-oss-nvidia-driver-gpu-ubuntu-22.04/latest/ami-id}"
FIS_ROLE="${FIS_ROLE:-kvevac-fis}"
TAG=kvevac-aws
PASS_THROUGH="MODEL MAX_MODEL_LEN VLLM_SPEC PREFILL_CONTEXTS PREFILL_REPEATS INTERFERENCE_REPEATS INTERFERENCE_CONTEXT KVEVAC_RESEND_S KVEVAC_JOB PHASE3_TIER PHASE3_RAM_GB PHASE3_CPU_GB PHASE3_SCALE PEER_IP PHASE3_SESSIONS PHASE3_NOTICE_S PHASE3_RATE_MBIT PHASE3_MAX_LEN PHASE3_GPU_UTIL PLANNER_RUN_MIN"

say() { printf '[%s] %s\n' "$(date -u +%H:%M:%S)" "$*"; }
die() { say "ERROR: $*"; exit 1; }
now() { date +%s; }

